package com.immersivedialogue;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class VoiceTypeTest
{
	/**
	 * Every declared blip must actually be on the classpath. {@link VoiceBlipPlayer} logs a missing resource at
	 * debug level and drops the blip, so a typo'd key would otherwise only show up as silence in game.
	 */
	@Test
	public void everyDeclaredResourceExists()
	{
		for (final VoiceType voice : VoiceType.values())
		{
			assertTrue(voice + " has no blips", voice.resources.length > 0);
			for (final String resource : voice.resources)
			{
				assertNotNull(
					voice + " is missing " + resource,
					VoiceType.class.getResource(resource));
			}
		}
	}
}

package com.immersivedialogue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import org.junit.Test;

public class VoiceClassifierTest
{
	@Test
	public void mapsCreatureKeywords()
	{
		assertEquals(VoiceType.IMP, VoiceClassifier.classify("Imp"));
		assertEquals(VoiceType.GOBLIN, VoiceClassifier.classify("Hobgoblin"));
		assertEquals(VoiceType.DEMON, VoiceClassifier.classify("Greater demon"));
		assertEquals(VoiceType.DRAGONKIN, VoiceClassifier.classify("Green dragon"));
		assertEquals(VoiceType.TROLL, VoiceClassifier.classify("Mountain Troll"));
		assertEquals(VoiceType.WRAITH, VoiceClassifier.classify("Ghost"));
		assertEquals(VoiceType.FAE, VoiceClassifier.classify("Fairy Godmother"));
		assertEquals(VoiceType.ORC, VoiceClassifier.classify("Orc"));
	}

	@Test
	public void fallsBackToMaleForUnknowns()
	{
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Hans"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Bob"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify(null));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify(""));
	}

	@Test
	public void shortKeywordsRequireWordStart()
	{
		// "orc" inside "Sorceress" must NOT read as an orc, nor "imp" inside "simple".
		assertNotEquals(VoiceType.ORC, VoiceClassifier.classify("Sorceress"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Simple Simon"));
		// A word-start short keyword still matches (Implings are imp-like Hunter creatures).
		assertEquals(VoiceType.IMP, VoiceClassifier.classify("Impling"));
	}

	@Test
	public void detectsFemaleTitlesAndRoles()
	{
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Woman"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Queen Ellamaria"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Witch"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Sorceress"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Lady Keli"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Bartender's wife"));
	}

	@Test
	public void detectsCuratedFemaleNames()
	{
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Gertrude"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Aggie"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Juliet"));
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceClassifier.classify("Ana"));
	}

	@Test
	public void detectsMaleAndUnknownNames()
	{
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Man"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Duke Horacio"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Romeo"));
	}

	@Test
	public void speciesWinsOverGender()
	{
		// "Godmother" contains "mother", but the species pass runs first.
		assertEquals(VoiceType.FAE, VoiceClassifier.classify("Fairy Godmother"));
		assertEquals(VoiceType.TROLL, VoiceClassifier.classify("Troll woman"));
	}

	@Test
	public void femaleKeywordsDoNotMatchMidWord()
	{
		// "aunt" in "Gauntlet"/"Haunted", "hag" in "Shaggy", "nun" in "Nunchaku", "maid" in "Maidstone".
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Gauntlet Attendant"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Haunted Mine Guard"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Shaggy"));
	}

	@Test
	public void curatedNamesMatchWholeWordsOnly()
	{
		// "ana" is a curated name, but must not fire inside "Banana" or "Anachronia".
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Banana seller"));
		assertEquals(VoiceType.HUMAN_MALE, VoiceClassifier.classify("Sarahs"));
	}

	@Test
	public void mapsPlayerVoiceToVoiceSets()
	{
		assertEquals(VoiceType.HUMAN_FEMALE, VoiceType.forPlayerVoice(PlayerVoice.VOICE_A));
		assertEquals(VoiceType.HUMAN_MALE, VoiceType.forPlayerVoice(PlayerVoice.VOICE_B));
		assertEquals(VoiceType.HUMAN_DEEP, VoiceType.forPlayerVoice(PlayerVoice.VOICE_C));
	}
}

package com.immersivedialogue;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ImmersiveDialoguePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ImmersiveDialoguePlugin.class);
		RuneLite.main(args);
	}
}

package com.immersivedialogue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import org.junit.Test;

public class ImmersiveDialogueConfigTest
{
	@Test
	public void hintSettingsPreserveExistingDisplayByDefault()
	{
		final ImmersiveDialogueConfig config = new ImmersiveDialogueConfig() { };

		assertTrue(config.showHints());
		assertEquals(new Color(255, 255, 255, 165), config.hintColor());
	}

	@Test
	public void playerVoiceDefaultsToTheOriginalSet()
	{
		// Voice B is the set the plugin has always used, so existing users hear no change on upgrade.
		final ImmersiveDialogueConfig config = new ImmersiveDialogueConfig() { };

		assertEquals(PlayerVoice.VOICE_B, config.playerVoice());
	}
}

package com.immersivedialogue;

import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Plays the bundled voice-blip WAVs as short, fire-and-forget sounds synced to the dialogue typewriter.
 *
 * <p>Playback goes through RuneLite's {@link AudioPlayer}, which loads the resource, opens a self-closing
 * audio line and starts it. That work is blocking IO plus line acquisition, so every blip is dispatched to a
 * single background thread — a frame must never block on audio or disk IO. {@link #play} only enqueues the
 * request and returns immediately; it never blocks or throws on the client thread.</p>
 *
 * <p>All audio is best-effort: on a machine with no mixer (headless CI, or {@code ./gradlew run} without an
 * output device) {@link AudioPlayer#play} simply fails and the blip is silently dropped. Nothing here ever
 * throws on the client thread.</p>
 */
@Slf4j
@Singleton
class VoiceBlipPlayer
{
	/**
	 * Cap on queued-but-not-yet-played blips. The typewriter can request blips faster than the audio
	 * subsystem opens lines; rather than build a backlog (and play blips after the line has finished
	 * typing), excess requests are dropped — a skipped blip is imperceptible.
	 */
	private static final int MAX_PENDING = 8;

	private final AudioPlayer audioPlayer;

	/**
	 * Single daemon thread that runs the blocking load/open/start off the client thread. Lazily
	 * (re)created by {@link #ensurePlayer} so toggling the plugin off and on again resumes playback;
	 * {@link #dispose} shuts it down.
	 */
	private ThreadPoolExecutor player;

	@Inject
	VoiceBlipPlayer(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	/**
	 * Play one blip at the given volume (1-100). Safe to call from the client thread: it only enqueues work
	 * and returns; it never opens a line, blocks, or throws. Dropped silently when the queue is saturated or
	 * the audio subsystem is unavailable.
	 */
	void play(String resourceKey, int volumePercent)
	{
		final float gainDb = gainFor(volumePercent);
		// DiscardPolicy silently drops the task when the queue is full or the executor is shutting down,
		// so execute() never throws and the client thread is never affected.
		ensurePlayer().execute(() ->
		{
			try
			{
				audioPlayer.play(VoiceBlipPlayer.class, resourceKey, gainDb);
			}
			catch (Exception e)
			{
				// Best-effort: unsupported format, no audio line, headless mixer, or missing resource.
				log.debug("Voice blip play skipped: {}", resourceKey, e);
			}
		});
	}

	/** Lazily (re)create the player thread. Synchronized against {@link #dispose}; cheap on the fast path. */
	private synchronized ThreadPoolExecutor ensurePlayer()
	{
		if (player == null || player.isShutdown())
		{
			player = new ThreadPoolExecutor(
				1, 1, 0L, TimeUnit.MILLISECONDS,
				new LinkedBlockingQueue<>(MAX_PENDING),
				r ->
				{
					final Thread t = new Thread(r, "immersive-dialogue-voice");
					t.setDaemon(true);
					return t;
				},
				new ThreadPoolExecutor.DiscardPolicy());
		}
		return player;
	}

	/**
	 * Map a 1-100 volume to a gain in decibels for {@link AudioPlayer}. Perceived loudness is logarithmic,
	 * so the linear fraction is converted to dB: 100% is 0 dB (native level) and 1% is about -40 dB. Floored
	 * at 1% because {@code log10(0)} is undefined.
	 */
	private static float gainFor(int volumePercent)
	{
		final float fraction = Math.max(1, volumePercent) / 100f;
		return (float) (20.0 * Math.log10(fraction));
	}

	/** Stop the player thread and release it. Called on plugin shutdown. */
	synchronized void dispose()
	{
		if (player != null)
		{
			player.shutdownNow();
			player = null;
		}
	}
}

package com.immersivedialogue;

/**
 * A voice "set" for dialogue blips and the bundled WAV resource keys backing it. The three human sets each
 * cycle through several blips for variety; each creature type plays its single characteristic blip (repeated
 * as the line types). Resource keys are absolute classpath paths loaded by {@link VoiceBlipPlayer}; the files
 * live under {@code src/main/resources/com/immersivedialogue/voice}.
 *
 * <p>The human sets serve two axes at once: the player picks one directly via {@link PlayerVoice}, while NPCs
 * are assigned {@link #HUMAN_FEMALE} or {@link #HUMAN_MALE} from their name by {@link VoiceClassifier}.
 * {@link #HUMAN_DEEP} is player-only — nothing classifies an NPC into it.</p>
 */
enum VoiceType
{
	/** Lighter/higher set. Voice A for the player, and the voice for NPCs read as female. */
	HUMAN_FEMALE(human("female_blip_1", "female_blip_2", "female_blip_3", "female_blip_4", "subtle_female_speech_blip")),
	/** The original set. Voice B for the player, the voice for NPCs read as male, and the overall fallback. */
	HUMAN_MALE(human("male_blip_1", "male_blip_2", "male_blip_3", "male_blip_4", "subtle_male_speech_blip")),
	/** Heavier/lower set. Voice C — player-only. */
	HUMAN_DEEP(human("deep_blip_1", "deep_blip_2", "deep_blip_3", "deep_blip_4", "subtle_deep_speech_blip")),
	DEMON(creature("demon")),
	DRAGONKIN(creature("dragonkin")),
	FAE(creature("fae")),
	GOBLIN(creature("goblin")),
	IMP(creature("imp")),
	ORC(creature("orc")),
	TROLL(creature("troll")),
	WRAITH(creature("wraith"));

	/** Absolute classpath keys for this voice's blip(s); never empty. */
	final String[] resources;

	VoiceType(String[] resources)
	{
		this.resources = resources;
	}

	/**
	 * The voice set behind a player's configured {@link PlayerVoice}. Lives here rather than on the enum so
	 * that the public config enum does not expose this package-private type.
	 */
	static VoiceType forPlayerVoice(PlayerVoice voice)
	{
		switch (voice)
		{
			case VOICE_A:
				return HUMAN_FEMALE;
			case VOICE_C:
				return HUMAN_DEEP;
			case VOICE_B:
			default:
				return HUMAN_MALE;
		}
	}

	private static String[] human(String... names)
	{
		final String[] keys = new String[names.length];
		for (int i = 0; i < names.length; i++)
		{
			keys[i] = "/com/immersivedialogue/voice/human/" + names[i] + ".wav";
		}
		return keys;
	}

	private static String[] creature(String name)
	{
		return new String[]{"/com/immersivedialogue/voice/creatures/" + name + "_speech_blip.wav"};
	}
}

package com.immersivedialogue;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the avatar backdrop panel behind the relocated chat-head.
 *
 * <p>Kept apart from {@link ImmersiveDialogueOverlay} purely because of layering: the chat-head is a real
 * MODEL widget (created by {@link DialogueWidgetController}), so its panel must be drawn on the
 * UNDER_WIDGETS layer to sit behind it, while the dialogue box and text are drawn ABOVE_WIDGETS so they
 * cover full-screen cutscene widgets. Both fade together via the controller's eased visibility.</p>
 */
class ImmersiveDialogueBackdropOverlay extends Overlay
{
	private final DialogueWidgetController controller;
	private final ImmersiveDialogueConfig config;

	@Inject
	ImmersiveDialogueBackdropOverlay(DialogueWidgetController controller, ImmersiveDialogueConfig config)
	{
		this.controller = controller;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		// UNDER_WIDGETS so the panel stays behind the live MODEL chat-head instead of painting over it.
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.avatarBackground())
		{
			return null;
		}

		// Only drawn when a head is actually relocated this frame (message boxes without a model have none).
		final Rectangle head = controller.getHeadBounds();
		if (head == null)
		{
			return null;
		}

		// Fade with the box: same eased visibility the dialogue overlay multiplies into its alpha.
		final float alpha = clamp01(controller.getDisplayAlpha());
		if (alpha <= 0f)
		{
			return null;
		}

		final Composite oldComposite = g.getComposite();
		if (alpha < 1f)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		}
		try
		{
			// Same padding, rounding and frame as the dialogue box so the two panels read as one surface.
			final int pad = config.backdropPadding();
			drawPanel(g, head.x - pad, head.y - pad, head.width + (pad * 2), head.height + (pad * 2),
				config.cornerRadius(), config.avatarBackgroundColor());
		}
		finally
		{
			g.setComposite(oldComposite);
		}

		return null;
	}

	/** Fills a backdrop panel (square when {@code radius == 0}, else rounded) and frames it if enabled. */
	private void drawPanel(Graphics2D g, int x, int y, int w, int h, int radius, Color fill)
	{
		g.setColor(fill);
		if (radius > 0)
		{
			g.fillRoundRect(x, y, w, h, radius, radius);
		}
		else
		{
			g.fillRect(x, y, w, h);
		}

		if (config.showBorder())
		{
			final int bw = config.borderWidth();
			final int half = bw / 2;
			final Stroke oldStroke = g.getStroke();
			g.setStroke(new BasicStroke(bw));
			g.setColor(config.borderColor());
			// Inset the stroke by half its width so the frame stays within the filled panel.
			if (radius > 0)
			{
				g.drawRoundRect(x + half, y + half, w - bw, h - bw, radius, radius);
			}
			else
			{
				g.drawRect(x + half, y + half, w - bw, h - bw);
			}
			g.setStroke(oldStroke);
		}
	}

	private static float clamp01(float v)
	{
		return v < 0f ? 0f : (v > 1f ? 1f : v);
	}
}

package com.immersivedialogue;

import java.awt.event.KeyEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.input.KeyListener;

/**
 * While the dialogue typewriter is still revealing a line, the first Space / Enter press finishes the reveal
 * instead of advancing: this listener consumes that one keystroke and tells the controller to skip. Once the
 * line is fully revealed it consumes nothing, so the next Space / Enter falls through to the game's own native
 * dialogue advance.
 *
 * <p>Like {@link DialogueMouseListener}, this only ever <b>consumes</b> an input event — it never synthesizes or
 * injects one, and never sends a game action.</p>
 */
@Singleton
class DialogueKeyListener implements KeyListener
{
	private final DialogueWidgetController controller;

	@Inject
	DialogueKeyListener(DialogueWidgetController controller)
	{
		this.controller = controller;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		final int code = e.getKeyCode();
		if ((code == KeyEvent.VK_SPACE || code == KeyEvent.VK_ENTER) && controller.isRevealing())
		{
			controller.requestSkip();
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}
}

package com.immersivedialogue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Maps an NPC's display name to a {@link VoiceType}. The client exposes no NPC "category" and no gender field
 * ({@code NPCComposition} has neither), so everything here is inferred from the speaker name available at
 * dialogue time. Matching is case-insensitive and runs in two passes:
 *
 * <ol>
 *     <li><b>Species</b> — creature keywords ("goblin", "demon", …) win outright, so "Fairy Godmother" is fae
 *     rather than female.</li>
 *     <li><b>Gender</b> — female titles/roles ("woman", "queen", "witch") and a curated set of female NPC
 *     first names select {@link VoiceType#HUMAN_FEMALE}.</li>
 * </ol>
 *
 * <p>Anything unmatched falls back to {@link VoiceType#HUMAN_MALE}. The species pass only fires for NPCs named
 * after their species — named creatures ("Elvarg", "Grubfoot") read as human, which is a known limitation of
 * name-only classification.</p>
 *
 * <p>Each keyword declares how it may match. {@link Match#WORD_START} keywords are ones that appear inside
 * unrelated names — "orc" in "Sorceress", "aunt" in "Gauntlet", "hag" in "Shaggy" — while
 * {@link Match#ANYWHERE} keywords are long enough to be safe as substrings ("goblin" in "Hobgoblin"). The
 * rule lists below are the single place to extend or correct coverage.</p>
 */
final class VoiceClassifier
{
	/** How a keyword is allowed to match within a name. */
	private enum Match
	{
		/** Matches as a plain substring. Only for keywords long/distinctive enough not to collide. */
		ANYWHERE,
		/** Matches only at the start of a word (string start, or after a non-letter). */
		WORD_START
	}

	private static final class Rule
	{
		private final String keyword;
		private final Match match;
		private final VoiceType voice;

		private Rule(String keyword, Match match, VoiceType voice)
		{
			this.keyword = keyword;
			this.match = match;
			this.voice = voice;
		}

		private boolean matches(String name)
		{
			return match == Match.ANYWHERE ? name.contains(keyword) : startsWord(name, keyword);
		}
	}

	/** Species keywords, most-specific first; the first match wins. */
	private static final List<Rule> SPECIES = new ArrayList<>();

	/** Female titles and roles. Checked only after {@link #SPECIES}. */
	private static final List<Rule> FEMALE_TITLES = new ArrayList<>();

	/**
	 * Female NPC first names, matched against the name's individual words. Names carry no gender signal of
	 * their own, so this is a curated list. Deliberately conservative: a wrong entry misgenders an NPC on
	 * every line, whereas a missing one merely falls back to male — the behaviour every NPC has today. Only
	 * add names you have confirmed in game.
	 */
	private static final Set<String> FEMALE_NAMES = new HashSet<>(Arrays.asList(
		"aggie", "alice", "ana", "betty", "caroline", "cassie", "catherine", "chaeldar",
		"doris", "elena", "ellamaria", "emily", "frenita", "gertrude", "gudrun", "hannah",
		"hetty", "juliet", "katrine", "keli", "lucy", "maria", "martha", "nieve",
		"sarah", "senliten", "sigrid", "sophie", "thessalia", "trudi", "valaine", "vanessa",
		"veronica", "xenia", "zanik", "zenesha"
	));

	static
	{
		// Order matters within each pass: the first matching rule wins.
		species("imp", Match.WORD_START, VoiceType.IMP);
		species("demon", Match.ANYWHERE, VoiceType.DEMON);
		species("devil", Match.ANYWHERE, VoiceType.DEMON);
		species("abyssal", Match.ANYWHERE, VoiceType.DEMON);
		species("dragonkin", Match.ANYWHERE, VoiceType.DRAGONKIN);
		species("dragon", Match.ANYWHERE, VoiceType.DRAGONKIN);
		species("wyrm", Match.ANYWHERE, VoiceType.DRAGONKIN);
		species("wyvern", Match.ANYWHERE, VoiceType.DRAGONKIN);
		species("troll", Match.ANYWHERE, VoiceType.TROLL);
		species("goblin", Match.ANYWHERE, VoiceType.GOBLIN);
		species("orc", Match.WORD_START, VoiceType.ORC);
		species("fairy", Match.ANYWHERE, VoiceType.FAE);
		species("faerie", Match.ANYWHERE, VoiceType.FAE);
		species("fae", Match.WORD_START, VoiceType.FAE);
		species("nymph", Match.ANYWHERE, VoiceType.FAE);
		species("pixie", Match.ANYWHERE, VoiceType.FAE);
		species("wraith", Match.ANYWHERE, VoiceType.WRAITH);
		species("ghost", Match.ANYWHERE, VoiceType.WRAITH);
		species("shade", Match.ANYWHERE, VoiceType.WRAITH);
		species("spectre", Match.ANYWHERE, VoiceType.WRAITH);
		species("revenant", Match.ANYWHERE, VoiceType.WRAITH);
		species("skeleton", Match.ANYWHERE, VoiceType.WRAITH);
		species("zombie", Match.ANYWHERE, VoiceType.WRAITH);

		// Female titles and roles. Short or embeddable keywords must start a word: "hag" hides in "Shaggy",
		// "aunt" in "Gauntlet"/"Haunted", "nun" in "Nunchaku", "maid" in "Maidstone", "dame" in "Adamant".
		female("woman", Match.ANYWHERE);
		female("girl", Match.ANYWHERE);
		female("lady", Match.ANYWHERE);
		female("queen", Match.ANYWHERE);
		female("princess", Match.ANYWHERE);
		female("duchess", Match.ANYWHERE);
		female("countess", Match.ANYWHERE);
		female("empress", Match.ANYWHERE);
		female("witch", Match.ANYWHERE);
		female("sorceress", Match.ANYWHERE);
		female("enchantress", Match.ANYWHERE);
		female("priestess", Match.ANYWHERE);
		female("abbess", Match.ANYWHERE);
		female("banshee", Match.ANYWHERE);
		female("mermaid", Match.ANYWHERE);
		female("siren", Match.ANYWHERE);
		female("matron", Match.ANYWHERE);
		female("nurse", Match.ANYWHERE);
		female("barmaid", Match.ANYWHERE);
		female("waitress", Match.ANYWHERE);
		female("seamstress", Match.ANYWHERE);
		female("huntress", Match.ANYWHERE);
		female("mistress", Match.ANYWHERE);
		female("grandmother", Match.ANYWHERE);
		female("mother", Match.ANYWHERE);
		female("sister", Match.ANYWHERE);
		female("widow", Match.ANYWHERE);
		female("maiden", Match.ANYWHERE);
		female("wife", Match.WORD_START);
		female("maid", Match.WORD_START);
		female("dame", Match.WORD_START);
		female("aunt", Match.WORD_START);
		female("nun", Match.WORD_START);
		female("hag", Match.WORD_START);
	}

	private VoiceClassifier()
	{
	}

	/**
	 * The voice for an NPC speaker name: its species voice if the name names a species, otherwise
	 * {@link VoiceType#HUMAN_FEMALE} when the name reads as female, otherwise {@link VoiceType#HUMAN_MALE}
	 * (also the result for a null or empty name).
	 */
	static VoiceType classify(String npcName)
	{
		if (npcName == null || npcName.isEmpty())
		{
			return VoiceType.HUMAN_MALE;
		}
		final String name = npcName.toLowerCase(Locale.ROOT);

		for (final Rule rule : SPECIES)
		{
			if (rule.matches(name))
			{
				return rule.voice;
			}
		}
		for (final Rule rule : FEMALE_TITLES)
		{
			if (rule.matches(name))
			{
				return rule.voice;
			}
		}
		return hasFemaleName(name) ? VoiceType.HUMAN_FEMALE : VoiceType.HUMAN_MALE;
	}

	/** True if any whole word of the name is a known female first name (so "Aggie" hits, "Aggression" does not). */
	private static boolean hasFemaleName(String name)
	{
		for (final String word : name.split("[^a-z]+"))
		{
			if (!word.isEmpty() && FEMALE_NAMES.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	/** True if {@code keyword} appears in {@code name} at the start of a word (string start or after a non-letter). */
	private static boolean startsWord(String name, String keyword)
	{
		int from = 0;
		int idx;
		while ((idx = name.indexOf(keyword, from)) >= 0)
		{
			if (idx == 0 || !Character.isLetter(name.charAt(idx - 1)))
			{
				return true;
			}
			from = idx + 1;
		}
		return false;
	}

	private static void species(String keyword, Match match, VoiceType voice)
	{
		SPECIES.add(new Rule(keyword, match, voice));
	}

	private static void female(String keyword, Match match)
	{
		FEMALE_TITLES.add(new Rule(keyword, match, VoiceType.HUMAN_FEMALE));
	}
}

package com.immersivedialogue;

/**
 * Selectable voice-blip set for the local player's own dialogue lines. Config enums are surfaced in the
 * RuneLite settings panel, so this is public and renders via {@link #toString()}.
 *
 * <p>Deliberately named A / B / C rather than by gender: the sets differ only in pitch, and players pick
 * whichever suits their character. {@link #VOICE_B} is the default and is the set the plugin has always
 * used, so existing users hear no change.</p>
 */
public enum PlayerVoice
{
	VOICE_A("Voice A (lighter)"),
	VOICE_B("Voice B (default)"),
	VOICE_C("Voice C (heavier)");

	private final String label;

	PlayerVoice(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.immersivedialogue;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the translucent dialogue box plus the speaker name, body text and options. Rendered on the
 * ABOVE_WIDGETS layer so the box shows OVER full-screen cutscene widgets (the game's FADE_OVERLAY) that
 * would otherwise hide it. The animated head is a separate MODEL widget rendered by
 * {@link DialogueWidgetController}, just outside this box on the speaker's natural side; its backdrop panel
 * is drawn behind it by {@link ImmersiveDialogueBackdropOverlay} on the UNDER_WIDGETS layer so the head
 * always sits over its own backdrop.
 */
class ImmersiveDialogueOverlay extends Overlay
{
	// Package-private: the controller reads these to size the adaptive options box (see optionsBoxHeight).
	static final int INSET = 16;
	static final int LINE_GAP = 3;
	static final int OPTION_PAD = 7;
	static final int OPTION_GAP = 8;
	/** Lower bound for scaled font sizes so text stays legible at small scales (shared with optionsBoxHeight). */
	static final int MIN_FONT_PX = 8;
	private static final String CONTINUE_TEXT = "Press Space to continue";
	private static final String SKIP_TEXT = "Press Space to skip";

	private final DialogueWidgetController controller;
	private final ImmersiveDialogueConfig config;

	@Inject
	ImmersiveDialogueOverlay(DialogueWidgetController controller, ImmersiveDialogueConfig config)
	{
		this.controller = controller;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		// ABOVE_WIDGETS so the box + text render OVER full-screen cutscene widgets (the game's FADE_OVERLAY),
		// which would otherwise hide an UNDER_WIDGETS box while the chat-head (a real widget) stayed visible.
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final Rectangle b = controller.getBounds();
		if (b == null)
		{
			return null;
		}

		// Fade: scale every alpha the overlay draws by the controller's eased visibility. Done with a
		// composite so the backdrop, border, avatar panel and text all fade together as one surface.
		final float alpha = clamp01(controller.getDisplayAlpha());
		if (alpha <= 0f)
		{
			return null;
		}

		final Composite oldComposite = g.getComposite();
		if (alpha < 1f)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		}
		try
		{
			final int radius = config.cornerRadius();

			// Avatar backdrop is drawn by ImmersiveDialogueBackdropOverlay (UNDER_WIDGETS) so it stays behind
			// the live MODEL chat-head; this overlay (ABOVE_WIDGETS) draws only the box + text.

			// Main backdrop.
			final int pad = config.backdropPadding();
			drawPanel(g, b.x - pad, b.y - pad, b.width + (pad * 2), b.height + (pad * 2),
				radius, config.backgroundColor());

			// Scale the text with the box: the configured sizes are the 100% reference, multiplied by the
			// dialogue scale and floored so they stay legible. Spacing constants are scaled at each use site.
			final float s = scale();
			final int titlePx = Math.max(MIN_FONT_PX, scaled(config.titleFontSize(), s));
			final int bodyPx = Math.max(MIN_FONT_PX, scaled(config.textSize(), s));
			final Font nameFont = FontManager.getRunescapeBoldFont().deriveFont((float) titlePx);
			final Font bodyFont = FontManager.getRunescapeFont().deriveFont((float) bodyPx);
			final Color nameColor = config.nameColor();
			final Color textColor = config.textColor();

			switch (controller.getKind())
			{
				case NPC:
				case PLAYER:
				case CHAT_BOTH:
				case MESSAGE:
				case MESSAGE_TITLED:
				case NOTIFICATION:
				case MESSAGE_URL:
				case OBJECT:
				case OBJECT_DOUBLE:
				case LEVELUP:
					// All text-bearing kinds share one path. MESSAGE/URL have no speaker name (null); the titled /
					// notification narration boxes use their title as the header. OBJECT(_DOUBLE) show an item model
					// beside the box, LEVELUP the levelled skill's model, CHAT_BOTH the speaker's head — all
					// rendered through the head pipeline.
					drawConversation(g, b, nameFont, bodyFont, nameColor, textColor, s);
					break;
				case OPTIONS:
					drawOptions(g, b, nameFont, bodyFont, nameColor, textColor, s);
					break;
				default:
					break;
			}
		}
		finally
		{
			g.setComposite(oldComposite);
		}

		return null;
	}

	/** Fills a backdrop panel (square when {@code radius == 0}, else rounded) and frames it if enabled. */
	private void drawPanel(Graphics2D g, int x, int y, int w, int h, int radius, Color fill)
	{
		g.setColor(fill);
		if (radius > 0)
		{
			g.fillRoundRect(x, y, w, h, radius, radius);
		}
		else
		{
			g.fillRect(x, y, w, h);
		}

		if (config.showBorder())
		{
			final int bw = config.borderWidth();
			final int half = bw / 2;
			final Stroke oldStroke = g.getStroke();
			g.setStroke(new BasicStroke(bw));
			g.setColor(config.borderColor());
			// Inset the stroke by half its width so the frame stays within the filled panel.
			if (radius > 0)
			{
				g.drawRoundRect(x + half, y + half, w - bw, h - bw, radius, radius);
			}
			else
			{
				g.drawRect(x + half, y + half, w - bw, h - bw);
			}
			g.setStroke(oldStroke);
		}
	}

	private static float clamp01(float v)
	{
		return v < 0f ? 0f : (v > 1f ? 1f : v);
	}

	/** Current dialogue scale factor (1.0 = 100%). */
	private float scale()
	{
		return config.scalePercent() / 100f;
	}

	/** A base constant scaled by {@code s}. Mirrors DialogueWidgetController.scaled so the two never drift. */
	private static int scaled(int v, float s)
	{
		return Math.round(v * s);
	}

	private void drawConversation(Graphics2D g, Rectangle b, Font nameFont, Font bodyFont,
		Color nameColor, Color textColor, float s)
	{
		final int maxWidth = b.width - (scaled(INSET, s) * 2);
		final List<Line> lines = new ArrayList<>();

		final String name = controller.getSpeakerName();
		if (name != null && !name.isEmpty())
		{
			lines.add(new Line(name, nameFont, nameColor, -1));
		}

		final String body = controller.getBodyText();
		if (body != null && !body.isEmpty())
		{
			final FontMetrics bfm = g.getFontMetrics(bodyFont);
			// Typewriter: wrap the FULL body (stable line breaks that never reflow as characters appear), then
			// clip the drawn glyphs to the revealed character budget. getRevealedChars() is MAX_VALUE when not
			// revealing, so the whole body draws exactly as before.
			int remaining = controller.getRevealedChars();
			for (final String wrapped : wrap(body, bfm, maxWidth))
			{
				if (remaining <= 0)
				{
					break;
				}
				final String shown = wrapped.length() <= remaining ? wrapped : wrapped.substring(0, remaining);
				remaining -= shown.length();
				lines.add(new Line(shown, bodyFont, textColor, -1));
			}
		}

		drawTextBlock(g, b, lines, s);
		if (config.showHints())
		{
			drawBottomHint(g, b, bodyFont, controller.isRevealing() ? SKIP_TEXT : CONTINUE_TEXT, s);
		}
	}

	/**
	 * A bottom-centered hint line (e.g. "Press Space to continue" / "Use keys [1] - [N] …").
	 */
	private void drawBottomHint(Graphics2D g, Rectangle b, Font font, String text, float s)
	{
		final FontMetrics fm = g.getFontMetrics(font);
		final int x = b.x + ((b.width - fm.stringWidth(text)) / 2);
		final int y = b.y + b.height - fm.getDescent() - (scaled(INSET, s) / 2);

		g.setFont(font);
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(config.hintColor());
		g.drawString(text, x, y);
	}

	private void drawOptions(Graphics2D g, Rectangle b, Font nameFont, Font bodyFont,
		Color nameColor, Color textColor, float s)
	{
		final List<Line> lines = new ArrayList<>();
		int maxKey = 0;
		for (final DialogueWidgetController.Option option : controller.getOptions())
		{
			// Child subid 0 is the "Select an Option" header: render it as the title.
			final boolean header = option.subid == 0;
			// Mirror Quest Helper's highlight in our own legible color (detection used QH's real color).
			final Color color = option.highlighted ? config.questHelperHighlightColor()
				: (header ? nameColor : textColor);
			if (header)
			{
				lines.add(new Line(option.text, nameFont, color, -1));
				continue;
			}
			maxKey = Math.max(maxKey, option.subid);
			// Prefix each selectable option with the number key that picks it (native 1-5 handling). The
			// "[N] " key marker is normally drawn in the hint color so it reads as a keyboard hint, like the
			// bottom line. But a Quest Helper highlight takes priority over the hint color: the "[N]" then
			// matches the option's highlight color so the whole line (number + text) reads as recommended.
			final String prefix = "[" + option.subid + "] ";
			final Color prefixColor = option.highlighted ? config.questHelperHighlightColor() : config.hintColor();
			lines.add(new Line(prefix + option.text, bodyFont, color, option.subid, prefix, prefixColor));
		}
		drawTextBlock(g, b, lines, s);
		if (config.showHints() && maxKey > 0)
		{
			// Tell the player which number keys drive the options (optionsBoxHeight reserves this line).
			final String hint = maxKey == 1 ? "Use key [1]" : ("Use keys [1] - [" + maxKey + "]");
			drawBottomHint(g, b, bodyFont, hint, s);
		}
	}

	/**
	 * Draws the lines top-aligned and horizontally centered. Option rows (non-negative subid) get extra
	 * vertical padding so the numbered choices are comfortably spaced.
	 */
	private void drawTextBlock(Graphics2D g, Rectangle b, List<Line> lines, float s)
	{
		if (lines.isEmpty())
		{
			return;
		}

		int y = b.y + scaled(INSET, s);
		for (final Line line : lines)
		{
			final FontMetrics fm = g.getFontMetrics(line.font);
			final int x = b.x + ((b.width - fm.stringWidth(line.text)) / 2);

			if (line.subid >= 0)
			{
				// Option row: padded and comfortably spaced.
				final int optPad = scaled(OPTION_PAD, s);
				final int rowH = fm.getAscent() + fm.getDescent() + (optPad * 2);
				final int baseline = y + optPad + fm.getAscent();
				g.setFont(line.font);
				g.setColor(Color.BLACK);
				g.drawString(line.text, x + 1, baseline + 1);
				if (line.prefix != null)
				{
					// Draw the "[N]" key marker in the hint color, then the option text in its own color.
					g.setColor(line.prefixColor);
					g.drawString(line.prefix, x, baseline);
					g.setColor(line.color);
					g.drawString(line.text.substring(line.prefix.length()),
						x + fm.stringWidth(line.prefix), baseline);
				}
				else
				{
					g.setColor(line.color);
					g.drawString(line.text, x, baseline);
				}
				y += rowH + scaled(OPTION_GAP, s);
			}
			else
			{
				// Plain line (title / body / "Select an Option" header): original tight spacing.
				y += fm.getAscent();
				g.setFont(line.font);
				// shadow for legibility
				g.setColor(Color.BLACK);
				g.drawString(line.text, x + 1, y + 1);
				g.setColor(line.color);
				g.drawString(line.text, x, y);
				y += fm.getDescent() + scaled(LINE_GAP, s);
			}
		}
	}

	private static List<String> wrap(String text, FontMetrics fm, int maxWidth)
	{
		final List<String> out = new ArrayList<>();
		for (final String paragraph : text.split("\n", -1))
		{
			final String[] words = paragraph.split(" ");
			StringBuilder cur = new StringBuilder();
			for (final String word : words)
			{
				final String probe = cur.length() == 0 ? word : cur + " " + word;
				if (fm.stringWidth(probe) <= maxWidth)
				{
					cur.setLength(0);
					cur.append(probe);
				}
				else
				{
					if (cur.length() > 0)
					{
						out.add(cur.toString());
					}
					cur.setLength(0);
					cur.append(word);
				}
			}
			out.add(cur.toString());
		}
		return out;
	}

	private static final class Line
	{
		private final String text;
		private final Font font;
		private final Color color;
		/** Native option child index for a clickable option line, or {@code -1} for plain text. */
		private final int subid;
		/** Leading "[N] " key marker drawn in {@link #prefixColor}, or {@code null} for none. */
		private final String prefix;
		private final Color prefixColor;

		private Line(String text, Font font, Color color, int subid)
		{
			this(text, font, color, subid, null, null);
		}

		private Line(String text, Font font, Color color, int subid, String prefix, Color prefixColor)
		{
			this.text = text;
			this.font = font;
			this.color = color;
			this.subid = subid;
			this.prefix = prefix;
			this.prefixColor = prefixColor;
		}
	}
}

package com.immersivedialogue;

