	@Range(min = 50, max = 150)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "scalePercent",
		name = "Dialogue scale",
		description = "Scale the whole dialogue - box, avatar and text - as one unit. 100% is the default.",
		section = sizeSection,
		position = 0
	)
